import unittest

from src.customer import customer_total
from src.invoice import invoice_total
from src.pricing_percent import apply


class PercentRegressionTests(unittest.TestCase):
    def test_percent_units_and_rounding_across_consumers(self):
        for calculate in (apply, invoice_total, customer_total):
            for amount, percent, expected in (
                (100, 10, 90),
                (200, 25, 150),
                (100, 0.1, 99.9),
                (19.99, 12.5, 17.49),
                (100, 0, 100),
                (100, 100, 0),
            ):
                with self.subTest(calculate=calculate.__name__, percent=percent):
                    self.assertEqual(calculate(amount, percent), expected)

    def test_existing_validation_reaches_all_consumers(self):
        for calculate in (apply, invoice_total, customer_total):
            for percent in (-0.1, 100.1, float("nan")):
                with self.subTest(calculate=calculate.__name__, percent=percent):
                    with self.assertRaisesRegex(ValueError, "^percent out of range$"):
                        calculate(100, percent)
            for percent in (None, "10"):
                with self.subTest(calculate=calculate.__name__, percent=percent):
                    with self.assertRaises(TypeError):
                        calculate(100, percent)

